import { useEffect, useState } from "react";
import type { ReactNode } from "react";
import { api } from "../../api";
import { Icon } from "../../Icon";
import { ConfirmActionDialog, IntelligenceUnavailableBoundary } from "../../intelligence/IntelligencePrimitives";
import { ProposalIntelligenceResult } from "../../intelligence/ProposalIntelligenceResult";
import { loadProposal, proposalCommand, proposalHeaders } from "./api";
import { asList, asRecord, control, currentStageNumber, displayDate, field, labelize, text } from "./helpers";
import { sourceLabels } from "./registry";
import { lifecycleStages, type JsonRecord, type ProposalDetail, type ProposalRole } from "./types";

const ownerRoles = new Set<ProposalRole>(["SYSTEM_ADMIN", "OWNER_SPONSOR", "COMMERCIAL_APPROVER"]);
const engineeringRoles = new Set<ProposalRole>(["SYSTEM_ADMIN", "OWNER_SPONSOR", "RESPONSIBLE_ENGINEER"]);

export function ProposalWorkspacePage({ role, proposalId, onBack }: { role: ProposalRole; proposalId: string; onBack: () => void }) {
  const [proposal, setProposal] = useState<ProposalDetail | null>(null);
  const [activeSection, setActiveSection] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");
  const [dialog, setDialog] = useState<{ title: string; consequence: string; confirmLabel: string; action: () => Promise<void> } | null>(null);
  const refresh = async () => { setLoading(true); try { setProposal(await loadProposal(role, proposalId)); setError(""); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "Proposal workspace unavailable."); } finally { setLoading(false); } };
  useEffect(() => { void refresh(); }, [proposalId, role]);
  useEffect(() => { const onHash = () => { const value = Number(window.location.hash.replace("#stage-", "")); if (value >= 1 && value <= 5) setActiveSection(value); }; onHash(); window.addEventListener("hashchange", onHash); return () => window.removeEventListener("hashchange", onHash); }, []);
  const execute = async (action: () => Promise<void>) => { setDialog(null); setMessage(""); setError(""); try { await action(); await refresh(); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "The Proposal action was not completed."); } };
  const requestAction = (title: string, consequence: string, confirmLabel: string, action: () => Promise<void>) => setDialog({ title, consequence, confirmLabel, action });
  if (loading && !proposal) return <div className="proposal-feature-page"><div className="proposal-loading panel" role="status"><Icon name="refresh" size={18} /> Loading Proposal workspace…</div></div>;
  if (!proposal) return <div className="proposal-feature-page"><div className="proposal-alert error-state" role="alert"><Icon name="alert" size={18} /> {error || "Proposal not found."}<button type="button" className="button-secondary" onClick={onBack}>Return to Proposals</button></div></div>;
  const stageNumber = currentStageNumber(proposal.stage);
  return <div className="proposal-feature-page proposal-workspace-page">
    <header className="proposal-workspace-header"><div><button type="button" className="text-button proposal-back-button" onClick={onBack}><Icon name="arrow-left" size={14} /> Proposal register</button><span className="eyebrow">PROPOSAL WORKSPACE</span><h2>{proposal.title}</h2><div className="proposal-identity-line"><b>{proposal.proposal_reference}</b><span>Client · {text(proposal.client_name)}</span><span>Project · {text(proposal.project_reference, "Provisional")}</span></div></div><div className="proposal-header-state"><span className="tag">{proposal.stage_label}</span><b>Owner · {proposal.current_owner}</b><small>Last activity · {displayDate(proposal.last_activity)}</small></div></header>
    {(message || error) && <div className={error ? "proposal-alert error-state" : "proposal-alert inline-message"} role={error ? "alert" : "status"}><Icon name={error ? "alert" : "check"} size={16} /> <span>{error || message}</span>{error && <button type="button" className="text-button" onClick={() => setError("")}>Dismiss</button>}</div>}
    <Lifecycle current={stageNumber} active={activeSection} onSelect={(number) => { setActiveSection(number); window.history.replaceState({}, "", `${window.location.pathname}#stage-${number}`); }} />
    <div className="proposal-workspace-grid"><main className="proposal-stage-main"><ProposalIntelligencePanel proposal={proposal} role={role} setMessage={setMessage} setError={setError} /><StageHeading stage={lifecycleStages[activeSection - 1]} current={stageNumber} /><StageContent proposal={proposal} role={role} activeSection={activeSection} stageNumber={stageNumber} setProposal={setProposal} setMessage={setMessage} setError={setError} requestAction={requestAction} refresh={refresh} /></main><AttentionRail proposal={proposal} stageNumber={stageNumber} onSelect={(number) => { setActiveSection(number); window.location.hash = `stage-${number}`; }} /></div>
    {dialog && <ConfirmActionDialog title={dialog.title} consequence={dialog.consequence} confirmLabel={dialog.confirmLabel} onCancel={() => setDialog(null)} onConfirm={() => void execute(dialog.action)} />}
  </div>;
}

function Lifecycle({ current, active, onSelect }: { current: number; active: number; onSelect: (number: number) => void }) {
  return <nav className="proposal-lifecycle" aria-label="Proposal lifecycle">{lifecycleStages.map((stage) => { const state = stage.number < current ? "complete" : stage.number === current ? "current" : "future"; return <button type="button" key={stage.number} className={`proposal-lifecycle-step ${state} ${active === stage.number ? "selected" : ""}`} aria-current={active === stage.number ? "step" : undefined} onClick={() => onSelect(stage.number)}><span className="proposal-step-number">{state === "complete" ? "✓" : stage.number}</span><span><b>{stage.label}</b><small>{state === "current" ? "Current workspace" : state === "complete" ? "Completed · inspect" : "Future stage"}</small></span></button>; })}</nav>;
}

function StageHeading({ stage, current }: { stage: typeof lifecycleStages[number]; current: number }) {
  return <div className="proposal-stage-heading"><div><span className="eyebrow">STAGE {stage.number} · {stage.label.toUpperCase()}</span><h3>{stage.description}</h3></div><span className={stage.number === current ? "proposal-stage-pill current" : "proposal-stage-pill"}>{stage.number === current ? "Current stage" : stage.number < current ? "Completed · read-only review" : "Future stage"}</span></div>;
}

function ProposalIntelligencePanel({ proposal, role, setMessage, setError }: { proposal: ProposalDetail; role: ProposalRole; setMessage: (value: string) => void; setError: (value: string) => void }) {
  const [operation, setOperation] = useState("tender-intake-analysis");
  const [result, setResult] = useState<JsonRecord | null>(null);
  const [reviews, setReviews] = useState<JsonRecord[]>([]);
  const [busy, setBusy] = useState(false);
  const requiresAccepted = operation === "lpo-variance-analysis" || operation === "handoff-preflight";
  const loadReviews = async () => { try { const response = await api<{ items: JsonRecord[] }>(`/api/bd/proposals/${proposal.id}/intelligence/reviews`, { headers: proposalHeaders(role) }); setReviews(response.items || []); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "Proposal Intelligence review could not be loaded."); } };
  const run = async () => { setBusy(true); setError(""); try { const invocationId = crypto.randomUUID(); const response = await api<JsonRecord>(`/api/bd/proposals/${proposal.id}/intelligence`, { method: "POST", headers: { ...proposalHeaders(role), "Content-Type": "application/json" }, body: JSON.stringify({ operation, idempotency_key: `proposal-intelligence:${proposal.id}:${operation}:${invocationId}` }) }); setResult(response); setMessage("Proposal Intelligence result is ready for human review; no protected Proposal action was taken."); await loadReviews(); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "Proposal Intelligence could not be run."); } finally { setBusy(false); } };
  const decide = async (binding: JsonRecord, decision: string) => { try { await api<JsonRecord>(`/api/bd/proposals/${proposal.id}/intelligence/reviews/${binding.binding_id}/decision`, { method: "POST", headers: { ...proposalHeaders(role), "Content-Type": "application/json" }, body: JSON.stringify({ decision, idempotency_key: `proposal-review-${binding.binding_id}-${decision}`, precondition_version: text(binding.precondition_version) }) }); setMessage(`Proposal Intelligence review ${decision.toLowerCase()} recorded. Protected Proposal actions remain separate.`); await loadReviews(); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "Proposal Intelligence review was rejected."); } };
  const output = result?.output && typeof result.output === "object" ? asRecord(result.output) : (reviews.length ? asRecord(reviews[reviews.length - 1].output) : null);
  const outputOperation = text(result?.skill_id, "").replace("proposal.", "") || text(reviews[reviews.length - 1]?.skill_id, operation).replace("proposal.", "");
  const citations = asList(result?.citations || reviews[reviews.length - 1]?.citations);
  return <section className="proposal-surface panel proposal-intelligence-panel" aria-label="Proposal Intelligence"><div className="panel-head"><div><span className="eyebrow">PROPOSAL · INTELLIGENCE</span><h3>Proposal Intelligence</h3></div><span className="proposal-stage-pill">{result ? "Human review required" : requiresAccepted ? "Accepted revision required" : "Review-only assistance"}</span></div><p className="muted">Structured, source-grounded assistance stays inside this Proposal. It cannot verify facts, Accept the Proposal, release commercially, or create a Contract handoff.</p><div className="proposal-inline-form"><label>Operation<select aria-label="Proposal Intelligence operation" value={operation} onChange={(event) => setOperation(event.target.value)}><option value="tender-intake-analysis">Intake · Analyze Tender</option><option value="requirement-evidence-analysis">Requirements &amp; Evidence Gaps</option><option value="section-draft">Draft with Evidence</option><option value="commercial-consistency-review">Commercial Consistency Review</option><option value="lpo-variance-analysis">LPO Compare</option><option value="handoff-preflight">Handoff Preflight</option></select></label><button type="button" className="button-secondary" onClick={() => void run()} disabled={busy || (requiresAccepted && !proposal.current_revision)}>{busy ? "Running…" : "Run Proposal Intelligence"}</button>{requiresAccepted && !proposal.current_revision && <small className="muted">This capability is available after a human accepted Proposal revision.</small>}{!requiresAccepted && !proposal.draft_revision && <small className="muted">A current working revision will be created by the server.</small>}</div>{output && <ProposalIntelligenceResult operation={outputOperation || operation} output={output} citations={citations} />}{reviews.length > 0 && <div className="proposal-inline-form"><strong>Proposal-owned review work</strong>{reviews.map((item) => <span key={text(item.binding_id)}>{text(item.skill_id, "Proposal result")} · {text(item.work_product_state, "UNKNOWN")} · {Boolean(item.actionable) ? "Actionable" : "Rerun required"}{Boolean(item.actionable) && <><button type="button" className="text-button" onClick={() => void decide(item, "ACCEPT")}>Accept review</button><button type="button" className="text-button" onClick={() => void decide(item, "CORRECT")}>Correct</button><button type="button" className="text-button" onClick={() => void decide(item, "REJECT")}>Reject</button><button type="button" className="text-button" onClick={() => void decide(item, "DEFER")}>Defer</button><button type="button" className="text-button" onClick={() => void decide(item, "ESCALATE")}>Escalate</button></>}</span>)}</div>}</section>;
}

function StageContent({ proposal, role, activeSection, stageNumber, setProposal, setMessage, setError, requestAction, refresh }: { proposal: ProposalDetail; role: ProposalRole; activeSection: number; stageNumber: number; setProposal: (proposal: ProposalDetail) => void; setMessage: (value: string) => void; setError: (value: string) => void; requestAction: (title: string, consequence: string, label: string, action: () => Promise<void>) => void; refresh: () => Promise<void> }) {
  if (activeSection === 1) return <IntakeStage proposal={proposal} role={role} stageNumber={stageNumber} setProposal={setProposal} setMessage={setMessage} setError={setError} requestAction={requestAction} refresh={refresh} />;
  if (activeSection === 2) return <EngineeringStage proposal={proposal} role={role} stageNumber={stageNumber} setProposal={setProposal} setMessage={setMessage} setError={setError} requestAction={requestAction} refresh={refresh} />;
  if (activeSection === 3) return <><CommercialStage proposal={proposal} role={role} stageNumber={stageNumber} setProposal={setProposal} setMessage={setMessage} setError={setError} requestAction={requestAction} refresh={refresh} /><CommercialParity proposal={proposal} role={role} setProposal={setProposal} setMessage={setMessage} setError={setError} /></>;
  if (activeSection === 4) return <><ClientResponseStructuredControls proposal={proposal} role={role} stageNumber={stageNumber} setProposal={setProposal} setMessage={setMessage} setError={setError} requestAction={requestAction} refresh={refresh} /><LpoStructuredComparison proposal={proposal} role={role} setProposal={setProposal} setMessage={setMessage} setError={setError} /></>;
  return <HandoffStage proposal={proposal} role={role} stageNumber={stageNumber} setProposal={setProposal} setMessage={setMessage} setError={setError} requestAction={requestAction} refresh={refresh} />;
}

function StagePanel({ eyebrow, title, description, children }: { eyebrow: string; title: string; description?: string; children: ReactNode }) {
  return <section className="proposal-surface panel"><div className="panel-head"><div><span className="eyebrow">{eyebrow}</span><h3>{title}</h3></div>{description && <small>{description}</small>}</div>{children}</section>;
}

function IntakeStage({ proposal, role, stageNumber, setProposal, setMessage, setError, requestAction, refresh }: StageProps) {
  const [client, setClient] = useState(field(proposal, "client_name", proposal.client_name || "")); const [description, setDescription] = useState(field(proposal, "project_description", proposal.title)); const [scope, setScope] = useState(field(proposal, "client_scope_of_work")); const [budget, setBudget] = useState(field(proposal, "client_budget")); const [timing, setTiming] = useState(field(proposal, "requested_timing")); const [constraints, setConstraints] = useState(field(proposal, "client_constraints")); const [additional, setAdditional] = useState(field(proposal, "additional_information")); const [origin, setOrigin] = useState(field(proposal, "lead_origin", "Other")); const [contactName, setContactName] = useState(text(asRecord(asRecord(proposal.forms_v2).proposal_contact).display_name, "")); const [contactEmail, setContactEmail] = useState(text(asRecord(asRecord(proposal.forms_v2).proposal_contact).email, "")); const [mobile, setMobile] = useState(text(asRecord(asRecord(proposal.forms_v2).proposal_contact).mobile, "")); const [note, setNote] = useState(""); const [noteType, setNoteType] = useState("CLIENT_CLARIFICATION");
  const save = async () => { try { const result = await api<ProposalDetail>(`/api/bd/proposals/${proposal.id}`, { method: "PATCH", headers: { ...proposalHeaders(role), "Content-Type": "application/json" }, body: JSON.stringify({ fields: { ...proposal.fields, client_name: client, project_description: description, client_scope_of_work: scope, client_budget: budget, requested_timing: timing, client_constraints: constraints, additional_information: additional, lead_origin: origin }, expected_updated_at: proposal.updated_at }) }); setProposal(result); setMessage("Intake context saved and read back from the Proposal service."); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "Intake could not be saved."); } };
  const saveContact = async () => { try { const result = await api<ProposalDetail>(`/api/bd/proposals/${proposal.id}/contact`, { method: "PUT", headers: { ...proposalHeaders(role), "Content-Type": "application/json" }, body: JSON.stringify({ display_name: contactName, email: contactEmail, mobile, purpose: "PROPOSAL_CONTACT", status: "HUMAN_ENTERED" }) }); setProposal(result); setMessage("Proposal contact saved and read back from the canonical contact context."); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "Proposal contact could not be saved."); } };
  const addNote = async () => { if (!note.trim()) return; try { const result = await api<ProposalDetail>(`/api/bd/proposals/${proposal.id}/notes`, { method: "POST", headers: { ...proposalHeaders(role), "Content-Type": "application/json" }, body: JSON.stringify({ note_type: noteType, content: note.trim() }) }); setProposal(result); setNote(""); setMessage(`${labelize(noteType)} saved as human-entered context.`); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "Note could not be saved."); } };
  const proceed = async () => { const result = await api<JsonRecord>(`/api/bd/proposals/${proposal.id}/proceed`, { method: "POST", headers: proposalHeaders(role) }); if (result.proposal && typeof result.proposal === "object") setProposal(result.proposal as ProposalDetail); setMessage("Intake completed. Engineering Preparation is now the next step."); };
  return <><StagePanel eyebrow="SOURCE / EVIDENCE CENTER" title="Evidence Center" description="Actual source records remain distinct from human notes and machine candidates."><EvidenceCenter proposal={proposal} role={role} setProposal={setProposal} setMessage={setMessage} setError={setError} /></StagePanel><StagePanel eyebrow="CLIENT / REQUEST" title="Client and Proposal context" description="Editable before Engineering handoff; canonical identity stays server-owned."><div className="proposal-form-grid"><label>Client<input aria-label="Client" value={client} onChange={(event) => setClient(event.target.value)} /></label><label>Proposal Contact<input aria-label="Proposal contact" value={contactName} onChange={(event) => setContactName(event.target.value)} /></label><label>Contact Email<input aria-label="Contact email" type="email" value={contactEmail} onChange={(event) => setContactEmail(event.target.value)} /></label><label>Mobile<input aria-label="Mobile" value={mobile} onChange={(event) => setMobile(event.target.value)} /></label><label className="proposal-form-wide">Project Description<textarea aria-label="Project description" value={description} onChange={(event) => setDescription(event.target.value)} /></label><label className="proposal-form-wide">Client Requested Scope<textarea aria-label="Client requested scope" value={scope} onChange={(event) => setScope(event.target.value)} /></label><label>Client Budget<input aria-label="Client budget" value={budget} onChange={(event) => setBudget(event.target.value)} /></label><label>Requested Timing<input aria-label="Requested timing" value={timing} onChange={(event) => setTiming(event.target.value)} /></label><label className="proposal-form-wide">Client Constraints<textarea aria-label="Client constraints" value={constraints} onChange={(event) => setConstraints(event.target.value)} /></label><label className="proposal-form-wide">Additional Information<textarea aria-label="Additional information" value={additional} onChange={(event) => setAdditional(event.target.value)} /></label><label>Lead origin<select aria-label="Lead origin" value={origin} onChange={(event) => setOrigin(event.target.value)}><option>Tender / RFP</option><option>Email enquiry</option><option>Referral</option><option>Marketing</option><option>Web / Google</option><option>Personal / relationship</option><option>Other</option></select></label></div><div className="proposal-actions"><button type="button" className="button-secondary" onClick={() => void save()}>Save intake context</button><button type="button" className="button-secondary" onClick={() => void saveContact()}>Save Proposal contact</button></div></StagePanel><SiteAndPeople proposal={proposal} role={role} setProposal={setProposal} setMessage={setMessage} setError={setError} /><StagePanel eyebrow="CONVERSATIONS / OPEN ITEMS" title="Notes, unknowns, and conflicts" description="Unknown ≠ conflict ≠ assumption. Human context is not verified evidence."><OpenItems proposal={proposal} /><div className="proposal-inline-form"><select aria-label="Note type" value={noteType} onChange={(event) => setNoteType(event.target.value)}><option value="CALL_NOTE">Call Note</option><option value="MEETING_NOTE">Meeting Note</option><option value="CLIENT_CLARIFICATION">Client Clarification</option></select><input aria-label="Client clarification note" placeholder="Add a call, meeting, or client clarification note" value={note} onChange={(event) => setNote(event.target.value)} /><button type="button" className="button-secondary" onClick={() => void addNote()} disabled={!note.trim()}>Add note</button></div></StagePanel><ReadinessCard proposal={proposal} role={role} stageNumber={stageNumber} onProceed={() => requestAction("Proceed to Engineering Preparation", "This records the human handoff from Intake & Sources. It does not confirm scope or authorize commercial activity.", "Proceed to Engineering", proceed)} refresh={refresh} /></>;
}

function EvidenceCenter({ proposal, role, setProposal, setMessage, setError }: Pick<StageProps, "proposal" | "role" | "setProposal" | "setMessage" | "setError">) {
  const [sourceType, setSourceType] = useState("TENDER_DOCUMENT"); const [file, setFile] = useState<File | null>(null); const [busy, setBusy] = useState(false);
  const upload = async () => { if (!file) return; setBusy(true); const body = new FormData(); body.append("source_type", sourceType); body.append("file", file); try { const result = await api<JsonRecord>(`/api/bd/proposals/${proposal.id}/sources`, { method: "POST", headers: proposalHeaders(role), body }); if (result.proposal && typeof result.proposal === "object") setProposal(result.proposal as ProposalDetail); setFile(null); setMessage(`${sourceLabels[sourceType] || labelize(sourceType)} registered in the Evidence Center.`); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "Evidence could not be registered."); } finally { setBusy(false); } };
  const sources = proposal.sources || [];
  return <><div className="evidence-summary"><b>{sources.length} source record{sources.length === 1 ? "" : "s"}</b><span>Currentness, classification, and provenance are available on each record.</span></div><div className="evidence-record-list">{sources.map((source, index) => <article className="evidence-record" key={text(source.id, `source-${index}`)}><div className="evidence-record-icon"><Icon name="library" size={18} /></div><div><b>{text(source.source_title ?? source.source_filename, "Untitled source")}</b><span>{sourceLabels[text(source.source_type, "")] || labelize(source.source_type)} · {text(source.verification_state ?? source.status, "Observed")}</span><small>DocumentVersion · {text(source.document_version_id ?? source.source_revision, "Not captured")} · {displayDate(source.created_at)}</small></div><span className="evidence-state">{text(source.currentness_state ?? source.status, "CURRENT")}</span></article>)}{!sources.length && <div className="proposal-empty-inline"><Icon name="empty" size={17} /><span>No source evidence yet. Add the first record or continue without a source.</span></div>}</div><div className="proposal-inline-form evidence-add"><select aria-label="Evidence source family" value={sourceType} onChange={(event) => setSourceType(event.target.value)}><option value="TENDER_EMAIL">Tender Email</option><option value="TENDER_DOCUMENT">Tender Document</option><option value="TENDER_PHOTO">Tender Photo / Image</option><option value="CLIENT_DATA">Client Information</option></select><input aria-label="Evidence file" type="file" accept={sourceType === "TENDER_PHOTO" ? "image/*" : undefined} onChange={(event) => setFile(event.target.files?.[0] || null)} /><button type="button" className="button-secondary" onClick={() => void upload()} disabled={busy || !file}>{busy ? "Registering…" : "Add source evidence"}</button></div></>;
}

function SiteAndPeople({ proposal, role, setProposal, setMessage, setError }: Pick<StageProps, "proposal" | "role" | "setProposal" | "setMessage" | "setError">) {
  const site = asRecord(asRecord(proposal.forms_v2).site_context); const stakeholders = asList(asRecord(proposal.forms_v2).stakeholders); const [location, setLocation] = useState(text(site.location_text, "")); const [plot, setPlot] = useState(text(site.plot_text, "")); const [area, setArea] = useState(text(site.area_value, "")); const [unit, setUnit] = useState(text(site.area_unit, "m²")); const [areaKind, setAreaKind] = useState(text(site.area_kind, "NOT_SPECIFIED")); const [description, setDescription] = useState(text(site.site_description, "")); const [stakeholderName, setStakeholderName] = useState(""); const [stakeholderRole, setStakeholderRole] = useState("OTHER");
  const save = async () => { try { const result = await api<ProposalDetail>(`/api/bd/proposals/${proposal.id}/site-context`, { method: "PUT", headers: { ...proposalHeaders(role), "Content-Type": "application/json" }, body: JSON.stringify({ location_text: location, plot_text: plot, area_value: area || undefined, area_unit: unit, area_kind: areaKind, site_description: description }) }); setProposal(result); setMessage("Site and property context saved."); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "Site context could not be saved."); } };
  const addStakeholder = async () => { if (!stakeholderName.trim()) return; try { const result = await api<ProposalDetail>(`/api/bd/proposals/${proposal.id}/stakeholders`, { method: "POST", headers: { ...proposalHeaders(role), "Content-Type": "application/json" }, body: JSON.stringify({ role_code: stakeholderRole, display_snapshot: { name: stakeholderName.trim() }, status: "UNKNOWN" }) }); setProposal(result); setStakeholderName(""); setMessage("Stakeholder recorded with its display snapshot."); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "Stakeholder could not be saved."); } };
  return <StagePanel eyebrow="SITE / PROPERTY / STAKEHOLDERS" title="Site and client context" description="Area basis is explicit; blank is not silently treated as N/A."><div className="proposal-form-grid"><label>Location<input aria-label="Site location" value={location} onChange={(event) => setLocation(event.target.value)} /></label><label>Plot / property reference<input aria-label="Plot or property reference" value={plot} onChange={(event) => setPlot(event.target.value)} /></label><label>Area value<input aria-label="Area value" value={area} onChange={(event) => setArea(event.target.value)} /></label><label>Area unit<input aria-label="Area unit" value={unit} onChange={(event) => setUnit(event.target.value)} /></label><label>Area basis<select aria-label="Area basis" value={areaKind} onChange={(event) => setAreaKind(event.target.value)}><option value="GROSS">Gross</option><option value="NET">Net</option><option value="PLOT">Plot</option><option value="BUILT_UP">Built-up</option><option value="OTHER">Other</option><option value="NOT_SPECIFIED">Not specified</option></select></label><label className="proposal-form-wide">Site description<textarea aria-label="Site description" value={description} onChange={(event) => setDescription(event.target.value)} /></label></div><div className="stakeholder-list">{stakeholders.map((item, index) => <div key={text(item.id, `stakeholder-${index}`)}><b>{text(asRecord(item.display_snapshot).name, "Unnamed stakeholder")}</b><span>{labelize(item.role_code)} · {labelize(item.status)}</span></div>)}{!stakeholders.length && <span className="muted">No stakeholders recorded.</span>}</div><div className="proposal-inline-form"><select aria-label="Stakeholder role" value={stakeholderRole} onChange={(event) => setStakeholderRole(event.target.value)}><option value="CLIENT_CONTACT">Client contact</option><option value="DECISION_MAKER">Decision maker</option><option value="CONSULTANT">Consultant</option><option value="OTHER">Other</option></select><input aria-label="Stakeholder display name" value={stakeholderName} onChange={(event) => setStakeholderName(event.target.value)} placeholder="Display name snapshot" /><button type="button" className="button-secondary" onClick={() => void addStakeholder()} disabled={!stakeholderName.trim()}>Add stakeholder</button></div><p className="muted">{stakeholders.length} stakeholder record(s) · {proposal.site_photos?.length || 0} site/project photo(s)</p><button type="button" className="button-secondary" onClick={() => void save()}>Save site context</button></StagePanel>;
}

function OpenItems({ proposal }: { proposal: ProposalDetail }) { const hardening = asRecord(proposal.hardening); const items: Array<JsonRecord & { kind: string }> = [...asList(hardening.unknowns).map((item) => ({ ...item, kind: "Unknown" })), ...asList(hardening.conflicts).map((item) => ({ ...item, kind: "Conflict" })), ...asList(hardening.assumptions).map((item) => ({ ...item, kind: "Assumption" }))]; return <div className="open-item-list">{items.length ? items.map((item, index) => <div key={text(item.id, `open-item-${index}`)}><span className="proposal-mini-label">{item.kind}</span><b>{text(item.statement ?? item.field_code, "Open item")}</b><small>{labelize(item.materiality ?? item.status)}</small></div>) : <div className="proposal-empty-inline">No unknowns, conflicts, or assumptions recorded.</div>}</div>; }

function EngineeringStage({ proposal, role, stageNumber, setProposal, setMessage, setError, requestAction, refresh }: StageProps) {
  const forms = asRecord(proposal.forms_v2); const [scope, setScope] = useState(field(proposal, "scope_of_work", field(proposal, "sow", ""))); const [process, setProcess] = useState(field(proposal, "process_of_work", "")); const [assessmentType, setAssessmentType] = useState("SITE_VISIT"); const [assessmentStatus, setAssessmentStatus] = useState("INCOMPLETE"); const [findings, setFindings] = useState(""); const [evidenceIds, setEvidenceIds] = useState(""); const [serviceCode, setServiceCode] = useState(""); const assessment = control(proposal, "technical_assessment"); const scopeConfirmation = control(proposal, "scope_confirmation"); const canTechnical = proposal.action_capabilities?.EDIT_TECHNICAL?.available ?? engineeringRoles.has(role); const canOwner = proposal.action_capabilities?.CONFIRM_SCOPE?.available ?? ownerRoles.has(role);
  const save = async () => { try { const result = await api<ProposalDetail>(`/api/bd/proposals/${proposal.id}`, { method: "PATCH", headers: { ...proposalHeaders(role), "Content-Type": "application/json" }, body: JSON.stringify({ fields: { ...proposal.fields, scope_of_work: scope, process_of_work: process }, expected_updated_at: proposal.updated_at }) }); setProposal(result); setMessage("Engineering preparation saved."); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "Engineering preparation could not be saved."); } };
  const assess = async () => { const result = await api<JsonRecord>(`/api/bd/proposals/${proposal.id}/technical-assessments`, { method: "POST", headers: { ...proposalHeaders(role), "Content-Type": "application/json" }, body: JSON.stringify({ assessment_type: assessmentType, status: assessmentStatus, findings: findings.trim() ? [{ code: "ENGINEERING_FINDING", disposition: assessmentStatus, note: findings.trim() }] : [], evidence_document_version_ids: evidenceIds.split(",").map((item) => item.trim()).filter(Boolean) }) }); if (result.control) setMessage(`Technical assessment ${assessmentStatus.toLowerCase()} recorded with human authority.`); };
  const confirmScope = async () => { await api(`/api/bd/proposals/${proposal.id}/scope-confirmations`, { method: "POST", headers: { ...proposalHeaders(role), "Content-Type": "application/json" }, body: JSON.stringify({ scope_statement: scope, service_offering_codes: [serviceCode.trim()], technical_assessment_ids: assessment?.id ? [assessment.id] : [] }) }); setMessage("AMEC Scope confirmed by a human operator."); };
  const eligible = async () => { await api(`/api/bd/proposals/${proposal.id}/service-eligibility`, { method: "POST", headers: { ...proposalHeaders(role), "Content-Type": "application/json" }, body: JSON.stringify({ service_offering_code: serviceCode.trim(), result: "ELIGIBLE", capability_reference: "configured-service-catalog", policy_reference: "configured-policy" }) }); setMessage("Service eligibility recorded from governed configuration."); };
  const ready = async () => { await api(`/api/proposals-main/proposals/${proposal.id}/engineering-ready`, { method: "POST", headers: proposalHeaders(role) }); setMessage("Engineering is ready for Commercial Review."); };
  return <><StagePanel eyebrow="CLIENT REQUEST" title="Pinned request context" description="The original client request remains visible while Engineering prepares AMEC interpretation."><div className="pinned-context"><b>{field(proposal, "client_scope_of_work", "Client scope not recorded")}</b><span>{field(proposal, "project_description", proposal.title)}</span><small>{proposal.sources.length} linked source record(s) · client context is not the confirmed AMEC Scope.</small></div></StagePanel><StagePanel eyebrow="TECHNICAL / SITE ASSESSMENT" title="Engineering review" description="Human technical assessment is separate from Scope confirmation."><div className="decision-grid"><DecisionStatus label="Assessment" value={text(assessment?.status, "Not recorded")} /><DecisionStatus label="Reviewer" value={text(assessment?.assessed_by, "Responsible Engineer")}/><DecisionStatus label="Linked evidence" value={text(assessment?.evidence_document_version_ids, "None selected")}/></div>{canTechnical ? <div className="proposal-inline-form"><select aria-label="Assessment type" value={assessmentType} onChange={(event) => setAssessmentType(event.target.value)}><option value="SITE_VISIT">Site Visit</option><option value="TENDER_REVIEW">Tender Review</option><option value="DRAWINGS">Drawings</option><option value="DOCUMENT_REVIEW">Document Review</option><option value="OTHER">Other</option></select><select aria-label="Assessment result" value={assessmentStatus} onChange={(event) => setAssessmentStatus(event.target.value)}><option value="PASS">Pass</option><option value="CONDITIONAL">Conditional</option><option value="BLOCKED">Blocked</option><option value="INCOMPLETE">Incomplete</option></select><input aria-label="Assessment findings" value={findings} onChange={(event) => setFindings(event.target.value)} placeholder="Findings and site context" /><input aria-label="Assessment evidence IDs" value={evidenceIds} onChange={(event) => setEvidenceIds(event.target.value)} placeholder="Exact DocumentVersion IDs, comma separated" /><button type="button" className="button-secondary" onClick={() => requestAction("Record technical assessment", "This records the human Engineering assessment. It does not confirm commercial scope or service eligibility.", "Record assessment", assess)}>Record assessment</button></div> : <p className="muted">Engineering assessment is read-only for this persona.</p>}</StagePanel><StagePanel eyebrow="AMEC TECHNICAL INTERPRETATION" title="Scope comparison" description="Client requested scope, AMEC interpretation, and confirmed commercial scope remain distinct."><div className="scope-comparison"><div><span>Client requested scope</span><p>{field(proposal, "client_scope_of_work")}</p></div><div><span>AMEC technical interpretation</span><textarea aria-label="AMEC technical interpretation" value={scope} onChange={(event) => setScope(event.target.value)} readOnly={!canTechnical} /></div><div><span>Confirmed commercial scope</span><p>{text(scopeConfirmation?.scope_statement, "Not confirmed")}</p></div></div><label>Engineering process of work<textarea aria-label="Engineering process of work" value={process} onChange={(event) => setProcess(event.target.value)} readOnly={!canTechnical} /></label>{canTechnical && <button type="button" className="button-secondary" onClick={() => void save()}>Save technical interpretation</button>}</StagePanel><StagePanel eyebrow="GOVERNED SERVICE DECISION" title="Scope confirmation and service eligibility" description="Business/system controls remain authoritative; selected offering codes are recorded explicitly."><div className="decision-grid"><DecisionStatus label="Scope confirmation" value={text(scopeConfirmation?.status, "Not recorded")} /><DecisionStatus label="Service eligibility" value={text(asList(asRecord(proposal.commercial_controls).service_eligibility)[0] && asRecord(asList(asRecord(proposal.commercial_controls).service_eligibility)[0]).result, "Not recorded")} /><DecisionStatus label="Policy / capability" value="Server-derived service decision"/></div>{canOwner && <div className="proposal-actions"><input aria-label="Service offering code" value={serviceCode} onChange={(event) => setServiceCode(event.target.value)} placeholder="Canonical service offering code" /><button type="button" className="button-secondary" onClick={() => requestAction("Confirm AMEC Scope", "This confirms the AMEC commercial scope. It does not accept the Proposal or authorize release.", "Confirm scope", confirmScope)} disabled={!scope.trim() || !serviceCode.trim() || !assessment?.id}>Confirm AMEC Scope</button><button type="button" className="button-secondary" onClick={() => requestAction("Record service eligibility", "This records a governed eligibility decision for the selected offering. It is not an AI recommendation.", "Record eligibility", eligible)} disabled={!serviceCode.trim()}>Record service eligibility</button></div>}</StagePanel><ReadinessCard proposal={proposal} role={role} stageNumber={stageNumber} onProceed={() => requestAction("Mark Engineering Ready for Commercial Review", "The confirmed technical package will be handed to Commercial Review. No Proposal acceptance or release occurs.", "Mark engineering ready", ready)} refresh={refresh} /></>;
}

function CommercialStage({ proposal, role, stageNumber, setProposal, setMessage, setError, requestAction, refresh }: StageProps) {
  const fields = proposal.fields; const config = asRecord(proposal.configuration); const template = asRecord(config.proposal_template); const checklist = asRecord(config.proposal_checklist); const accepted = asRecord(proposal.current_revision); const draft = asRecord(proposal.draft_revision); const [price, setPrice] = useState(field(proposal, "price", "")); const [currency, setCurrency] = useState(field(proposal, "currency", "QAR")); const [duration, setDuration] = useState(field(proposal, "duration", field(proposal, "period", ""))); const [terms, setTerms] = useState(field(proposal, "payment_terms", "")); const [inclusions, setInclusions] = useState(field(proposal, "inclusions", "")); const [exclusions, setExclusions] = useState(field(proposal, "exclusions", ""));
  const save = async () => { try { const result = await api<ProposalDetail>(`/api/bd/proposals/${proposal.id}`, { method: "PATCH", headers: { ...proposalHeaders(role), "Content-Type": "application/json" }, body: JSON.stringify({ fields: { ...fields, price, currency, duration, payment_terms: terms, inclusions, exclusions }, expected_updated_at: proposal.updated_at }) }); setProposal(result); setMessage("Commercial basis saved as the working Proposal revision."); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "Commercial basis could not be saved."); } };
  const accept = async () => { const result = await proposalCommand<ProposalDetail>(role, proposal.id, "accept"); setProposal(result); setMessage(`Proposal Revision R${text(asRecord(result.current_revision).revision_number)} accepted by a human operator.`); };
  const createRevision = async () => { const result = await proposalCommand<JsonRecord>(role, proposal.id, "revisions", { reason: "New working Proposal revision requested" }); if (result.proposal && typeof result.proposal === "object") setProposal(result.proposal as ProposalDetail); setMessage(`Working Proposal revision R${text(asRecord(result.revision).revision_number)} created from accepted history.`); };
  return <><StagePanel eyebrow="CONFIRMED SCOPE" title="Commercial basis" description="Engineering context is pinned read-only here; commercial changes create a working revision before acceptance."><p className="pinned-context">{text(control(proposal, "scope_confirmation")?.scope_statement, field(proposal, "scope_of_work", "Confirmed scope not recorded"))}</p><div className="proposal-form-grid"><label>AMEC fee<input aria-label="AMEC fee" value={price} onChange={(event) => setPrice(event.target.value)} readOnly={!ownerRoles.has(role)} /></label><label>Currency<select aria-label="Currency" value={currency} onChange={(event) => setCurrency(event.target.value)} disabled={!ownerRoles.has(role)}><option>QAR</option><option>USD</option><option>EUR</option></select></label><label>Payment terms<input aria-label="Payment terms" value={terms} onChange={(event) => setTerms(event.target.value)} readOnly={!ownerRoles.has(role)} /></label><label>Duration<input aria-label="Commercial duration" value={field(proposal, "duration", field(proposal, "period", "Not recorded"))} readOnly /></label></div>{ownerRoles.has(role) && <button type="button" className="button-secondary" onClick={() => void save()}>Save commercial basis</button>}</StagePanel><StagePanel eyebrow="GOVERNED CONTENT" title="Proposal content summary" description="Global master content is consumed, never edited, from this workspace."><div className="content-summary-grid"><ContentLink label="Proposal Template" item={template} /><ContentLink label="Proposal Checklist" item={checklist} /><ContentLink label="Definitions" item={asRecord(config.definitions)} /><ContentLink label="Engineering references" item={asRecord(config.engineering_references)} /></div></StagePanel><StagePanel eyebrow="REVISION / HUMAN ACCEPTANCE" title="Review the exact Proposal revision" description="Accepted history is immutable; working changes remain visible and separate."><div className="revision-summary"><DecisionStatus label="Working revision" value={draft.revision_number ? `R${text(draft.revision_number)}` : "Current working state"}/><DecisionStatus label="Accepted revision" value={accepted.revision_number ? `R${text(accepted.revision_number)}` : "None"}/><DecisionStatus label="Template / checklist" value={`${text(template.ref, "Unresolved")} · ${text(checklist.ref, "Unresolved")}`}/><DecisionStatus label="Warnings" value={`${asList(asRecord(proposal.validation).warnings).length}`}/></div><p className="muted">Accept checks the exact current Proposal revision, source freshness, required fields, and human commercial authority. No Contract or Project is created.</p>{ownerRoles.has(role) && stageNumber !== 1 && <div className="proposal-actions"><button type="button" className="button-primary" onClick={() => requestAction(`Accept Proposal Revision R${text(draft.revision_number || accepted.revision_number || 1)}`, "This freezes the exact current scope, commercial basis, source lineage, and governed content versions into immutable accepted history.", "Accept Proposal revision", accept)} disabled={asList(asRecord(proposal.validation).blockers).length > 0}>Accept Proposal Revision</button>{Boolean(accepted.revision_number) && <button type="button" className="button-secondary" onClick={() => requestAction("Create a new Proposal revision", "This creates a working revision from accepted history. It does not change the accepted revision.", "Create revision", createRevision)}>Create revision</button>}</div>}</StagePanel><ReadinessCard proposal={proposal} role={role} stageNumber={stageNumber} refresh={refresh} /></>;
}

function ClientResponseStructuredControls({ proposal, role, setProposal, setMessage, setError, requestAction }: StageProps) {
  const accepted = asRecord(proposal.current_revision); const release = control(proposal, "commercial_release"); const [channel, setChannel] = useState("EMAIL"); const [recipientPartyId, setRecipientPartyId] = useState(""); const [recipientContact, setRecipientContact] = useState(""); const [distributionEvidence, setDistributionEvidence] = useState(""); const [distributionVersion, setDistributionVersion] = useState(""); const [acceptanceVersion, setAcceptanceVersion] = useState(""); const [acceptanceEvidence, setAcceptanceEvidence] = useState(""); const [responseType, setResponseType] = useState("ACCEPTED"); const [responseNotes, setResponseNotes] = useState(""); const responses = asList(asRecord(proposal.hardening).client_responses); const canWrite = proposal.action_capabilities?.RECORD_DISTRIBUTION?.available ?? ownerRoles.has(role); const canRelease = proposal.action_capabilities?.AUTHORIZE_RELEASE?.available ?? ownerRoles.has(role);
  const command = async (path: string, payload: JsonRecord, message: string) => { try { const result = await proposalCommand<JsonRecord>(role, proposal.id, path, payload); if (result.proposal && typeof result.proposal === "object") setProposal(result.proposal as ProposalDetail); setMessage(message); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "Proposal response action failed."); } };
  const distribute = () => command("distribution", { channel, recipient_party_id: recipientPartyId || undefined, recipient_contact_reference: recipientContact || undefined, evidence_document_version_id: distributionVersion || undefined, evidence_reference: distributionEvidence }, "Distribution recorded against the selected accepted revision.");
  const verify = () => { const response = responses.find((item) => text(item.response_type) === "ACCEPTED"); return command("acceptance-verification", { client_response_id: response?.id, evidence_reference: acceptanceEvidence, evidence_document_version_id: acceptanceVersion || undefined, verification_note: "Human verification against the exact accepted revision." }, "Client acceptance verification recorded."); };
  const authorizeRelease = () => command("commercial-release", { accepted_revision_id: accepted.id }, "Commercial release authorized for the exact accepted revision.");
  const recordResponse = () => command("client-responses", { response_type: responseType, notes: responseNotes, idempotency_key: `p04c-${proposal.id}-${responseType}-${responseNotes}` }, `Client response ${labelize(responseType)} recorded.`);
  return <StagePanel eyebrow="DISTRIBUTION / ACCEPTANCE EVIDENCE" title="Exact release and response evidence" description="Channel, recipient, DocumentVersion, and human verification remain explicit."><div className="decision-grid"><DecisionStatus label="Accepted revision" value={accepted.revision_number ? `R${text(accepted.revision_number)}` : "Not accepted"} /><DecisionStatus label="Commercial release" value={text(release?.status, "Not authorized")} /><DecisionStatus label="Recorded responses" value={String(responses.length)} /></div><div className="proposal-form-grid"><label>Distribution channel<select aria-label="Distribution channel" value={channel} onChange={(event) => setChannel(event.target.value)} disabled={!canWrite}><option>EMAIL</option><option>CLIENT_PORTAL</option><option>SHARED_DRIVE</option><option>COURIER</option><option>OTHER</option></select></label><label>Recipient party ID<input aria-label="Recipient party ID" value={recipientPartyId} onChange={(event) => setRecipientPartyId(event.target.value)} readOnly={!canWrite} /></label><label>Recipient contact reference<input aria-label="Recipient contact reference" value={recipientContact} onChange={(event) => setRecipientContact(event.target.value)} readOnly={!canWrite} /></label><label>Distribution evidence reference<input aria-label="Distribution evidence reference" value={distributionEvidence} onChange={(event) => setDistributionEvidence(event.target.value)} readOnly={!canWrite} /></label><label>Distribution DocumentVersion ID<input aria-label="Distribution evidence DocumentVersion ID" value={distributionVersion} onChange={(event) => setDistributionVersion(event.target.value)} readOnly={!canWrite} /></label><label>Acceptance evidence reference<input aria-label="Acceptance evidence reference" value={acceptanceEvidence} onChange={(event) => setAcceptanceEvidence(event.target.value)} readOnly={!canWrite} /></label><label>Acceptance DocumentVersion ID<input aria-label="Acceptance evidence DocumentVersion ID" value={acceptanceVersion} onChange={(event) => setAcceptanceVersion(event.target.value)} readOnly={!canWrite} /></label></div><div className="proposal-inline-form"><select aria-label="Client response type" value={responseType} onChange={(event) => setResponseType(event.target.value)} disabled={!canWrite}><option value="ACCEPTED">Accepted</option><option value="DECLINED">Rejected</option><option value="CHANGE_REQUESTED">Change requested</option><option value="EXPIRED">Expired</option><option value="WITHDRAWN">Withdrawn</option></select><input aria-label="Client response notes" value={responseNotes} onChange={(event) => setResponseNotes(event.target.value)} placeholder="Human evidence notes" readOnly={!canWrite}/></div><div className="proposal-actions"><button type="button" className="button-secondary" onClick={() => requestAction("Authorize Commercial Release", "This authorizes distribution of the exact accepted Proposal revision. It does not claim that the Proposal was sent.", "Authorize release", authorizeRelease)} disabled={!canRelease || !accepted.id}>Authorize release</button><button type="button" className="button-secondary" onClick={() => requestAction("Record client response", "This appends a human-recorded external response against the current accepted Proposal revision.", "Record response", async () => recordResponse())} disabled={!canWrite || !accepted.id || !responseNotes.trim()}>Record client response</button><button type="button" className="button-secondary" onClick={() => requestAction("Record Proposal distribution", "This records the selected channel, recipient, and exact evidence. It does not verify acceptance.", "Record distribution", async () => distribute())} disabled={!canWrite || !accepted.id || !distributionEvidence.trim() || !distributionVersion.trim()}>Record distribution</button><button type="button" className="button-secondary" onClick={() => requestAction("Verify client acceptance", "This records human verification against the accepted revision. It does not create a Contract.", "Verify acceptance", async () => verify())} disabled={!canWrite || !acceptanceEvidence.trim() || !acceptanceVersion.trim()}>Verify client acceptance</button></div></StagePanel>;
}

function LpoStructuredComparison({ proposal, role, setProposal, setMessage, setError }: Pick<StageProps, "proposal" | "role" | "setProposal" | "setMessage" | "setError">) {
  const accepted = asRecord(proposal.current_revision); const [evidence, setEvidence] = useState(""); const [documentVersion, setDocumentVersion] = useState(""); const labels = ["scope", "fee_value", "currency", "duration_period", "payment_terms", "inclusions", "exclusions"]; const initial = Object.fromEntries(labels.map((key) => [key, { accepted_value: key === "scope" ? text(control(proposal, "scope_confirmation")?.scope_statement, field(proposal, "scope_of_work")) : field(proposal, key === "fee_value" ? "price" : key), client_value: "", disposition: "", note: "" }])); const [rows, setRows] = useState<Record<string, { accepted_value: string; client_value: string; disposition: string; note: string }>>(initial); const canWrite = proposal.action_capabilities?.RECONCILE_LPO?.available ?? ownerRoles.has(role);
  const update = (key: string, name: string, value: string) => setRows((current) => ({ ...current, [key]: { ...current[key], [name]: value } }));
  const reconcile = async () => { try { const result = await proposalCommand<JsonRecord>(role, proposal.id, "lpo-reconciliation", { applies: true, client_document_version_id: documentVersion || undefined, client_artifact_reference: evidence, comparisons: rows }); if (result.proposal && typeof result.proposal === "object") setProposal(result.proposal as ProposalDetail); setMessage("Structured PO/LPO comparison recorded from the exact client evidence."); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "PO/LPO comparison could not be recorded."); } };
  return <StagePanel eyebrow="STRUCTURED PO / LPO RECONCILIATION" title="Compare every commercial basis field" description="Blank is incomplete; N/A requires a reason; mismatch blocks handoff."><div className="lpo-table-wrap"><table className="lpo-table"><thead><tr><th>Field</th><th>Accepted Proposal</th><th>Client basis</th><th>Disposition</th><th>Note / N/A reason</th></tr></thead><tbody>{labels.map((key) => <tr key={key}><th>{labelize(key)}</th><td>{text(rows[key].accepted_value, "Not recorded")}</td><td><input aria-label={`${key} client basis`} value={rows[key].client_value} onChange={(event) => update(key, "client_value", event.target.value)} readOnly={!canWrite} /></td><td><select aria-label={`${key} disposition`} value={rows[key].disposition} onChange={(event) => update(key, "disposition", event.target.value)} disabled={!canWrite}><option value="">Select</option><option>MATCH</option><option>MISMATCH</option><option>NOT_APPLICABLE</option></select></td><td><input aria-label={`${key} comparison note`} value={rows[key].note} onChange={(event) => update(key, "note", event.target.value)} readOnly={!canWrite} /></td></tr>)}</tbody></table></div><div className="proposal-form-grid"><label>Client PO/LPO evidence reference<input aria-label="Structured LPO evidence reference" value={evidence} onChange={(event) => setEvidence(event.target.value)} readOnly={!canWrite} /></label><label>Client PO/LPO DocumentVersion ID<input aria-label="Structured LPO DocumentVersion ID" value={documentVersion} onChange={(event) => setDocumentVersion(event.target.value)} readOnly={!canWrite} /></label></div><button type="button" className="button-secondary" onClick={() => void reconcile()} disabled={!canWrite || !accepted.id || !evidence.trim() || !documentVersion.trim()}>Record structured reconciliation</button></StagePanel>;
}

function CommercialParity({ proposal, role, setProposal, setMessage, setError }: Pick<StageProps, "proposal" | "role" | "setProposal" | "setMessage" | "setError">) {
  const [duration, setDuration] = useState(field(proposal, "duration", field(proposal, "period", ""))); const [inclusions, setInclusions] = useState(field(proposal, "inclusions", "")); const [exclusions, setExclusions] = useState(field(proposal, "exclusions", "")); const canEdit = proposal.action_capabilities?.EDIT_COMMERCIAL?.available ?? ownerRoles.has(role);
  const save = async () => { try { const result = await api<ProposalDetail>(`/api/bd/proposals/${proposal.id}`, { method: "PATCH", headers: { ...proposalHeaders(role), "Content-Type": "application/json" }, body: JSON.stringify({ fields: { ...proposal.fields, duration, inclusions, exclusions }, expected_updated_at: proposal.updated_at }) }); setProposal(result); setMessage("Duration, inclusions, and exclusions saved to the working Proposal basis."); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "Commercial parity fields could not be saved."); } };
  return <StagePanel eyebrow="COMMERCIAL FIELD PARITY" title="Complete commercial basis" description="All accepted commercial fields remain explicit and revision-bound."><div className="proposal-form-grid"><label>Duration / period<input aria-label="Commercial parity duration" value={duration} onChange={(event) => setDuration(event.target.value)} readOnly={!canEdit} /></label><label>Inclusions<textarea aria-label="Commercial inclusions" value={inclusions} onChange={(event) => setInclusions(event.target.value)} readOnly={!canEdit} /></label><label>Exclusions<textarea aria-label="Commercial exclusions" value={exclusions} onChange={(event) => setExclusions(event.target.value)} readOnly={!canEdit} /></label></div>{canEdit && <button type="button" className="button-secondary" onClick={() => void save()}>Save commercial field parity</button>}</StagePanel>;
}

function ClientResponseStage({ proposal, role, stageNumber, setProposal, setMessage, setError, requestAction, refresh }: StageProps) {
  const releaseControl = control(proposal, "commercial_release"); const distribution = control(proposal, "distribution"); const verification = control(proposal, "acceptance_verification"); const lpo = control(proposal, "lpo_reconciliation"); const accepted = asRecord(proposal.current_revision); const responses = asList(asRecord(proposal.hardening).client_responses); const [responseType, setResponseType] = useState("ACCEPTED"); const [responseNotes, setResponseNotes] = useState(""); const [distributionChannel, setDistributionChannel] = useState("EMAIL"); const [recipientPartyId, setRecipientPartyId] = useState(""); const [recipientContact, setRecipientContact] = useState(""); const [distributionEvidence, setDistributionEvidence] = useState(""); const [distributionEvidenceVersion, setDistributionEvidenceVersion] = useState(""); const [acceptanceEvidence, setAcceptanceEvidence] = useState(""); const [acceptanceEvidenceVersion, setAcceptanceEvidenceVersion] = useState(""); const [lpoEvidence, setLpoEvidence] = useState(""); const [lpoEvidenceVersion, setLpoEvidenceVersion] = useState(""); const [lpoVariance, setLpoVariance] = useState("");
  const command = async (path: string, payload: unknown, message: string) => { const result = await proposalCommand<JsonRecord>(role, proposal.id, path, payload); if (result.proposal && typeof result.proposal === "object") setProposal(result.proposal as ProposalDetail); setMessage(message); };
  const recordResponse = async () => command("client-responses", { response_type: responseType, notes: responseNotes, idempotency_key: `p04-${proposal.id}-${responseType}-${responseNotes}` }, `Client response ${labelize(responseType)} recorded.`);
  const authorizeRelease = async () => command("commercial-release", { accepted_revision_id: accepted.id }, "Commercial release authorized for the exact accepted revision.");
  const distribute = async () => command("distribution", { channel: distributionChannel, recipient_party_id: recipientPartyId || undefined, recipient_contact_reference: recipientContact || undefined, evidence_document_version_id: distributionEvidenceVersion || undefined, evidence_reference: distributionEvidence }, "Distribution evidence recorded; sending remains separate from authorization.");
  const verify = async () => { const acceptedResponse = responses.find((item) => text(item.response_type) === "ACCEPTED"); return command("acceptance-verification", { client_response_id: acceptedResponse?.id, evidence_reference: acceptanceEvidence, evidence_document_version_id: acceptanceEvidenceVersion || undefined, verification_note: "Human verified against the exact accepted revision." }, "Client acceptance evidence verified by a human operator."); };
  const reconcile = async () => command("lpo-reconciliation", { applies: true, client_artifact_reference: lpoEvidence, client_document_version_id: lpoEvidenceVersion || undefined, variances: lpoVariance.trim() ? [{ field: "commercial_basis", note: lpoVariance.trim(), disposition: "MISMATCH" }] : [], fields_compared: lpoVariance.trim() ? ["commercial_basis"] : [] }, lpoVariance.trim() ? "PO/LPO reconciliation recorded as a variance." : "PO/LPO reconciliation recorded with zero variances.");
  const createRevision = async () => { const result = await proposalCommand<JsonRecord>(role, proposal.id, "revisions", { reason: "Client Change Requested" }); if (result.proposal && typeof result.proposal === "object") setProposal(result.proposal as ProposalDetail); setMessage("Working revision created from accepted history for client changes."); };
  return <><StagePanel eyebrow="RELEASED BASIS" title="Distribution and client response" description="Record what happened to the exact released Proposal revision; do not conflate sending with acceptance."><div className="decision-grid"><DecisionStatus label="Accepted revision" value={`R${text(accepted.revision_number, "Not accepted")}`} /><DecisionStatus label="Commercial release" value={text(releaseControl?.status, "Not authorized")} /><DecisionStatus label="Distribution" value={distribution ? `${text(distribution.channel)} · evidence retained` : "Not recorded"}/></div>{ownerRoles.has(role) && <div className="proposal-actions"><button type="button" className="button-secondary" onClick={() => requestAction("Authorize Commercial Release", "This authorizes distribution of the exact accepted Proposal revision. It does not claim that the Proposal was sent.", "Authorize release", authorizeRelease)} disabled={!accepted.id}>Authorize Commercial Release</button><label className="proposal-inline-field">Distribution evidence<input value={distributionEvidence} onChange={(event) => setDistributionEvidence(event.target.value)} placeholder="Portal/email/evidence reference" /></label><button type="button" className="button-secondary" onClick={() => requestAction("Record Proposal distribution", "This records the channel, recipient context, and evidence that distribution occurred. It does not verify client acceptance.", "Record distribution", distribute)} disabled={!distributionEvidence.trim()}>Record distribution</button></div>}</StagePanel><StagePanel eyebrow="CLIENT RESPONSE" title="Accepted, rejected, or change requested" description="A Change Requested response routes through a new revision, re-review, re-acceptance, and re-release."><div className="response-history">{responses.length ? responses.map((response, index) => <div key={text(response.id, `response-${index}`)}><span className="proposal-mini-label">{labelize(response.response_type)}</span><b>{text(response.notes, "No notes recorded")}</b><small>{text(response.recorded_by)} · {displayDate(response.recorded_at)} · revision {text(response.accepted_revision_id, "not pinned")}</small></div>) : <div className="proposal-empty-inline">No client response recorded.</div>}</div>{ownerRoles.has(role) && <div className="proposal-inline-form"><select aria-label="Client response type" value={responseType} onChange={(event) => setResponseType(event.target.value)}><option value="ACCEPTED">Accepted</option><option value="DECLINED">Rejected</option><option value="CHANGE_REQUESTED">Change requested</option><option value="EXPIRED">Expired</option><option value="WITHDRAWN">Withdrawn</option></select><input aria-label="Client response notes" value={responseNotes} onChange={(event) => setResponseNotes(event.target.value)} placeholder="Human evidence notes"/><button type="button" className="button-secondary" onClick={() => requestAction(`Record client response: ${labelize(responseType)}`, "This appends a human-recorded external response against the current accepted Proposal revision.", "Record response", recordResponse)}>Record response</button></div>}{responses.some((item) => text(item.response_type) === "CHANGE_REQUESTED") && ownerRoles.has(role) && <button type="button" className="text-button" onClick={() => requestAction("Create revised Proposal", "The accepted revision remains immutable. This creates a working revision for re-review.", "Create revision", createRevision)}>Create revised Proposal for client change</button>}</StagePanel><StagePanel eyebrow="ACCEPTANCE EVIDENCE" title="Verify client acceptance" description="Signed Proposal, PO/LPO, or correspondence must be tied to the accepted revision."><div className="decision-grid"><DecisionStatus label="Acceptance evidence" value={verification ? "VERIFIED" : "Not verified"}/><DecisionStatus label="Client response" value={responses.some((item) => text(item.response_type) === "ACCEPTED") ? "Accepted response recorded" : "Accepted response required"}/><DecisionStatus label="Verification authority" value="Human / server capability"/></div>{ownerRoles.has(role) && <div className="proposal-inline-form"><input aria-label="Client acceptance evidence" value={acceptanceEvidence} onChange={(event) => setAcceptanceEvidence(event.target.value)} placeholder="Signed Proposal / PO / correspondence reference"/><button type="button" className="button-secondary" onClick={() => requestAction("Verify Client Acceptance", "This records human verification of client acceptance against the released Proposal revision. AI cannot perform this action.", "Verify acceptance", verify)} disabled={!acceptanceEvidence.trim()}>Verify Client Acceptance</button></div>}</StagePanel><LpoComparison proposal={proposal} role={role} lpo={lpo} lpoEvidence={lpoEvidence} setLpoEvidence={setLpoEvidence} lpoVariance={lpoVariance} setLpoVariance={setLpoVariance} reconcile={reconcile} requestAction={requestAction} /><IntelligenceUnavailableBoundary items={asList(asRecord(proposal.intelligence).client_response)} /><ReadinessCard proposal={proposal} role={role} stageNumber={stageNumber} refresh={refresh} /></>;
}

function LpoComparison({ proposal, role, lpo, lpoEvidence, setLpoEvidence, lpoVariance, setLpoVariance, reconcile, requestAction }: { proposal: ProposalDetail; role: ProposalRole; lpo: JsonRecord | null; lpoEvidence: string; setLpoEvidence: (value: string) => void; lpoVariance: string; setLpoVariance: (value: string) => void; reconcile: () => Promise<void>; requestAction: (title: string, consequence: string, label: string, action: () => Promise<void>) => void }) {
  const accepted = asRecord(proposal.current_revision); const rows = [{ label: "Scope", accepted: text(control(proposal, "scope_confirmation")?.scope_statement, field(proposal, "scope_of_work")), client: "Enter from PO/LPO" }, { label: "Fee / Value", accepted: `${field(proposal, "price")} ${field(proposal, "currency", "QAR")}`, client: "Enter from PO/LPO" }, { label: "Duration", accepted: field(proposal, "duration", field(proposal, "period")), client: "Enter from PO/LPO" }, { label: "Payment Terms", accepted: field(proposal, "payment_terms"), client: "Enter from PO/LPO" }, { label: "Inclusions / Exclusions", accepted: `${field(proposal, "inclusions")} / ${field(proposal, "exclusions")}`, client: "Enter from PO/LPO" }];
  return <StagePanel eyebrow="PO / LPO RECONCILIATION" title="Structured commercial comparison" description="The backend result is authoritative. A variance blocks Contract handoff and requires a revised Proposal path."><div className="lpo-table-wrap"><table className="lpo-table"><thead><tr><th>Dimension</th><th>Accepted Proposal {accepted.revision_number ? `R${text(accepted.revision_number)}` : "basis"}</th><th>Client PO/LPO</th><th>Backend status</th></tr></thead><tbody>{rows.map((row) => <tr key={row.label}><th>{row.label}</th><td>{row.accepted}</td><td>{row.client}</td><td>{lpo ? text(lpo.result, "Recorded") : "Not reconciled"}</td></tr>)}</tbody></table></div>{lpo?.result === "MISMATCH" && <div className="proposal-alert warning-copy" role="alert"><Icon name="alert" size={16} /> Contract handoff blocked. Create a revised Proposal, re-accept/re-release it, and reconcile the corrected client basis again.</div>}<div className="proposal-inline-form"><input aria-label="LPO evidence reference" value={lpoEvidence} onChange={(event) => setLpoEvidence(event.target.value)} placeholder="PO/LPO evidence reference"/><input aria-label="LPO variance details" value={lpoVariance} onChange={(event) => setLpoVariance(event.target.value)} placeholder="Material variance (leave blank for zero variance)"/><button type="button" className="button-secondary" onClick={() => requestAction("Confirm PO/LPO Reconciliation", "This records the backend reconciliation result against the accepted Proposal revision. It does not accept a Contract.", "Record reconciliation", reconcile)} disabled={!lpoEvidence.trim()}>Record reconciliation</button></div><p className="muted">Final backend result: <b>{text(lpo?.result, "Not reconciled")}</b> · {Array.isArray(lpo?.variances) ? `${lpo?.variances.length} variance(s)` : "variance count unavailable"}</p></StagePanel>;
}

function HandoffStage({ proposal, role, stageNumber, setProposal, setMessage, setError, requestAction, refresh }: StageProps) {
  const controls = asRecord(proposal.commercial_controls); const handoff = control(proposal, "contract_handoff"); const accepted = asRecord(proposal.current_revision); const release = control(proposal, "commercial_release"); const distribution = control(proposal, "distribution"); const verification = control(proposal, "acceptance_verification"); const lpo = control(proposal, "lpo_reconciliation"); const [preflight, setPreflight] = useState<JsonRecord | null>(null); const canHandoff = proposal.action_capabilities?.RECORD_CONTRACT_HANDOFF?.available ?? ownerRoles.has(role);
  const preview = async () => { const result = await api<JsonRecord>(`/api/bd/proposals/${proposal.id}/handoff/contract`, { headers: proposalHeaders(role) }); setPreflight(result); setMessage(result.eligible ? "Ready for Contract Handoff." : `Handoff blocked: ${asList(result.blockers).map((item) => text(item.label ?? item)).join(", ")}`); };
  const record = async () => { const fresh = await api<JsonRecord>(`/api/bd/proposals/${proposal.id}/handoff/contract`, { headers: proposalHeaders(role) }); setPreflight(fresh); if (!fresh.eligible) throw new Error(`Handoff blocked: ${asList(fresh.blockers).join(", ")}`); const result = await proposalCommand<JsonRecord>(role, proposal.id, "handoff/contract-eligibility", {}); if (result.proposal && typeof result.proposal === "object") setProposal(result.proposal as ProposalDetail); setMessage("Contract handoff eligibility recorded. Contract acceptance and Project Activation remain separate."); };
  return <><StagePanel eyebrow="CONTRACT HANDOFF PREFLIGHT" title={handoff ? "Ready for Contract Handoff" : "Handoff preflight"} description="All gates are deterministic and traceable to the accepted Proposal basis."><div className="handoff-gate-list"><Gate label="Accepted Proposal revision" pass={Boolean(accepted.id)} value={accepted.revision_number ? `R${text(accepted.revision_number)}` : "Required"}/><Gate label="Commercial release" pass={Boolean(release)} value={text(release?.status, "Required")}/><Gate label="Distribution evidence" pass={Boolean(distribution)} value={distribution ? "Evidence retained" : "Required"}/><Gate label="Verified client acceptance" pass={Boolean(verification)} value={verification ? "Verified" : "Required"}/><Gate label="PO/LPO reconciliation" pass={Boolean(lpo && ["PASS", "NOT_APPLICABLE"].includes(text(lpo.result))) } value={text(lpo?.result, "Required")}/><Gate label="Scope and governed content" pass={Boolean(control(proposal, "scope_confirmation") && asRecord(proposal.configuration).proposal_template)} value="Current Proposal context"/></div><div className="proposal-actions"><button type="button" className="button-secondary" onClick={() => void preview()}>Preview handoff preflight</button>{canHandoff && <button type="button" className="button-primary" onClick={() => requestAction("Record Contract Handoff Eligibility", "This records eligibility only. It does not create or accept a Contract and does not activate a Project.", "Record handoff eligibility", record)} disabled={!preflight?.eligible}>Record Contract Handoff Eligibility</button>}</div>{preflight && <div className={preflight.eligible ? "proposal-alert inline-message" : "proposal-alert warning-copy"} role={preflight.eligible ? "status" : "alert"}>{preflight.eligible ? "Server preflight passed for the current accepted revision." : `Server preflight blocked: ${asList(preflight.blockers).map((item) => text(item.label ?? item)).join(", ")}`}</div>}</StagePanel><StagePanel eyebrow="DOWNSTREAM BOUNDARY" title="Separate Contract and Project decisions" description="Proposal handoff does not create downstream authority."><div className="boundary-callout"><Icon name="shield" size={18}/><div><b>Contract acceptance: separate decision</b><span>Project Activation: separate explicit Owner action</span><small>Proposal only proves whether the accepted commercial basis is eligible for handoff.</small></div></div></StagePanel><IntelligenceUnavailableBoundary items={asList(asRecord(proposal.intelligence).handoff)} /><ReadinessCard proposal={proposal} role={role} stageNumber={stageNumber} refresh={refresh} /></>;
}

function ReadinessCard({ proposal, role, stageNumber, onProceed, refresh }: { proposal: ProposalDetail; role: ProposalRole; stageNumber: number; onProceed?: () => void; refresh: () => Promise<void> }) { const readiness = asRecord(proposal.intake_readiness); const validation = asRecord(proposal.validation); const blockers = [...asList(readiness.blockers), ...asList(validation.blockers)]; return <StagePanel eyebrow="DETERMINISTIC READINESS" title={blockers.length ? "Action required" : stageNumber === 1 ? "Ready for Engineering" : "No blocking item"} description="Backend readiness is authoritative; no AI determines this state."><div className={blockers.length ? "readiness-blockers" : "readiness-ready"}>{blockers.length ? blockers.map((item, index) => <span key={text(item.code, `blocker-${index}`)}><Icon name="alert" size={14}/>{text(item.label ?? item, "Blocker")}</span>) : <span><Icon name="check" size={14}/>Proposal identity and current evidence remain auditable.</span>}</div>{stageNumber === 1 && onProceed && <button type="button" className="button-primary" onClick={onProceed} disabled={blockers.length > 0 || role === "RESPONSIBLE_ENGINEER"}>Proceed to Engineering Preparation</button>}<button type="button" className="text-button" onClick={() => void refresh()}><Icon name="refresh" size={14}/> Recheck backend readiness</button></StagePanel>; }

function AttentionRail({ proposal, stageNumber, onSelect }: { proposal: ProposalDetail; stageNumber: number; onSelect: (number: number) => void }) { const validation = asRecord(proposal.validation); const blockers = [...asList(asRecord(proposal.intake_readiness).blockers), ...asList(validation.blockers)]; const next = asRecord(proposal.next_action); const controls = asRecord(proposal.commercial_controls); return <aside className="proposal-attention-rail" aria-label="Proposal attention and state"><StagePanel eyebrow="NEXT AUTHORIZED ACTION" title={text(next.label, "Review Proposal")}><p>{text(next.reason, "The backend determines the next action from current business state.")}</p><span className="attention-owner">Current owner · {proposal.current_owner}</span>{typeof next.eligible === "boolean" && <span className={next.eligible ? "attention-ready" : "attention-blocked"}>{next.eligible ? "Eligible" : "Blocked"}</span>}</StagePanel><StagePanel eyebrow="ATTENTION / BLOCKERS" title={blockers.length ? `${blockers.length} item${blockers.length === 1 ? "" : "s"} need attention` : "No current blocker"}>{blockers.length ? <ul className="attention-list">{blockers.map((item, index) => <li key={text(item.code, `rail-blocker-${index}`)}><Icon name="alert" size={14}/>{text(item.label ?? item, "Blocker")}</li>)}</ul> : <p className="muted">The current Proposal can continue according to backend readiness.</p>}</StagePanel><StagePanel eyebrow="PROTECTED STATE" title="Business truth"><div className="rail-state-list"><RailState label="Scope" value={control(proposal, "scope_confirmation") ? "Confirmed" : "Not confirmed"}/><RailState label="Accepted Proposal" value={asRecord(proposal.current_revision).revision_number ? `R${text(asRecord(proposal.current_revision).revision_number)}` : "None"}/><RailState label="Release" value={control(proposal, "commercial_release") ? "Authorized" : "Not released"}/><RailState label="Client acceptance" value={control(proposal, "acceptance_verification") ? "Verified" : "Not verified"}/><RailState label="LPO" value={text(control(proposal, "lpo_reconciliation")?.result, "Not reconciled")}/><RailState label="Contract handoff" value={control(proposal, "contract_handoff") ? "Eligible" : "Not recorded"}/></div></StagePanel><StagePanel eyebrow="INTELLIGENCE STATE" title="Read-only assistance"><p className="muted">No Proposal skill is executable in this environment. There is no active Analyze, Generate, Ask AI, or Review button.</p><button type="button" className="text-button" onClick={() => onSelect(1)}>Open evidence context</button></StagePanel><StagePanel eyebrow="ADVANCED DETAILS" title="Audit identity"><dl className="advanced-details"><div><dt>Proposal ID</dt><dd>{proposal.id}</dd></div><div><dt>Stage code</dt><dd>{proposal.stage}</dd></div><div><dt>Source records</dt><dd>{asList(proposal.sources).length}</dd></div><div><dt>Contract eligible</dt><dd>{proposal.contract_eligible ? "true" : "false"}</dd></div></dl></StagePanel></aside>; }

function DecisionStatus({ label, value }: { label: string; value: string }) { return <div className="decision-status"><span>{label}</span><b>{value}</b></div>; }
function ContentLink({ label, item }: { label: string; item: JsonRecord }) { return <div className="content-summary-item"><Icon name="library" size={16}/><div><b>{label}</b><span>{text(item.ref ?? item.status, "Configuration required")}{item.version ? ` · v${text(item.version)}` : ""}</span><a href="/dashboard">View in Content Library <Icon name="arrow-up-right" size={13}/></a></div></div>; }
function Gate({ label, pass, value }: { label: string; pass: boolean; value: string }) { return <div className={pass ? "handoff-gate pass" : "handoff-gate blocked"}><Icon name={pass ? "check" : "alert"} size={16}/><span><b>{label}</b><small>{value}</small></span></div>; }
function RailState({ label, value }: { label: string; value: string }) { return <div><span>{label}</span><b>{value}</b></div>; }
type StageProps = { proposal: ProposalDetail; role: ProposalRole; stageNumber: number; setProposal: (proposal: ProposalDetail) => void; setMessage: (value: string) => void; setError: (value: string) => void; requestAction: (title: string, consequence: string, label: string, action: () => Promise<void>) => void; refresh: () => Promise<void> };
